//! Browser chrome styling for Firefox through `userChrome.css`.
//!
//! Firefox ignores the file unless `toolkit.legacyUserProfileCustomizations.stylesheets`
//! is enabled and the generated file is linked into the profile's `chrome/`
//! directory. My Linux writes the stylesheet; putting it in the profile is a
//! user choice because every Firefox profile has its own path.

use theme_engine::LoadedTheme;

use crate::{Integration, RenderError, require, validate_braces};

pub struct Firefox;

impl Integration for Firefox {
    fn id(&self) -> &'static str {
        "firefox"
    }

    fn name(&self) -> &'static str {
        "Firefox (userChrome.css)"
    }

    fn relative_path(&self) -> &'static str {
        "firefox/userChrome.css"
    }

    fn programs(&self) -> &'static [&'static str] {
        &["firefox"]
    }

    fn render(&self, theme: &LoadedTheme) -> String {
        render(theme)
    }

    fn validate(&self, content: &str) -> Result<(), RenderError> {
        require("firefox", content, ":root")?;
        require("firefox", content, "#TabsToolbar")?;
        require("firefox", content, "#nav-bar")?;
        require("firefox", content, "#urlbar-background")?;
        validate_braces(content)
    }
}

/// Generates Firefox chrome styling from the active theme.
pub fn render(theme: &LoadedTheme) -> String {
    let colors = &theme.colors;
    let typography = theme.typography_for("firefox");
    let metrics = theme.metrics_for("firefox");

    let mut output = String::new();

    output.push_str("/* Generated by My Linux Theme Engine. Do not edit manually. */\n");
    output.push_str("/* Enable toolkit.legacyUserProfileCustomizations.stylesheets */\n\n");

    output.push_str(":root {\n");
    output.push_str(&format!(
        "    --ml-background: {};\n",
        colors.background.to_hex()
    ));
    output.push_str(&format!("    --ml-surface: {};\n", colors.surface.to_hex()));
    output.push_str(&format!(
        "    --ml-surface-alt: {};\n",
        colors.surface_alt.to_hex()
    ));
    output.push_str(&format!("    --ml-primary: {};\n", colors.primary.to_hex()));
    output.push_str(&format!("    --ml-text: {};\n", colors.text.to_hex()));
    output.push_str(&format!(
        "    --ml-text-muted: {};\n",
        colors.text_muted.to_hex()
    ));
    output.push_str(&format!("    --ml-border: {};\n", colors.border.to_hex()));
    output.push_str(&format!("    --ml-radius: {}px;\n", metrics.radius));
    output.push_str(&format!("    --ml-font: \"{}\";\n", typography.font_family));
    output.push_str("}\n\n");

    output.push_str("#TabsToolbar {\n");
    output.push_str("    background: var(--ml-background) !important;\n");
    output.push_str("    color: var(--ml-text) !important;\n");
    output.push_str("    font-family: var(--ml-font) !important;\n");
    output.push_str(&format!(
        "    border-bottom: {}px solid var(--ml-border) !important;\n",
        metrics.border_width
    ));
    output.push_str("}\n\n");

    output.push_str(".tabbrowser-tab .tab-background {\n");
    output.push_str("    background: transparent !important;\n");
    output.push_str("    border-radius: var(--ml-radius) !important;\n");
    output.push_str("}\n\n");

    output.push_str(".tabbrowser-tab[selected] .tab-background {\n");
    output.push_str("    background: var(--ml-surface) !important;\n");
    output.push_str("    box-shadow: inset 0 -2px 0 var(--ml-primary) !important;\n");
    output.push_str("}\n\n");

    output.push_str(".tabbrowser-tab .tab-label {\n");
    output.push_str("    color: var(--ml-text-muted) !important;\n");
    output.push_str("}\n\n");

    output.push_str(".tabbrowser-tab[selected] .tab-label {\n");
    output.push_str("    color: var(--ml-text) !important;\n");
    output.push_str("}\n\n");

    output.push_str("#nav-bar {\n");
    output.push_str("    background: var(--ml-surface) !important;\n");
    output.push_str("    color: var(--ml-text) !important;\n");
    output.push_str("    font-family: var(--ml-font) !important;\n");
    output.push_str("}\n\n");

    output.push_str("#urlbar-background {\n");
    output.push_str("    background: var(--ml-background) !important;\n");
    output.push_str("    border: 1px solid var(--ml-border) !important;\n");
    output.push_str("    border-radius: var(--ml-radius) !important;\n");
    output.push_str("}\n\n");

    output.push_str("#urlbar-input {\n");
    output.push_str("    color: var(--ml-text) !important;\n");
    output.push_str("}\n\n");

    output.push_str("#PersonalToolbar {\n");
    output.push_str("    background: var(--ml-background) !important;\n");
    output.push_str("}\n\n");

    output.push_str("#urlbar[open] > #urlbar-background {\n");
    output.push_str("    background: var(--ml-surface-alt) !important;\n");
    output.push_str("    border-color: var(--ml-primary) !important;\n");
    output.push_str("}\n");

    output
}

#[cfg(test)]
mod tests {
    use super::*;
    use theme_engine::Registry;

    fn theme() -> LoadedTheme {
        Registry::new(vec!["../../themes".into()])
            .load("cyberpunk")
            .expect("cyberpunk should load")
    }

    #[test]
    fn renders_browser_surfaces() {
        let css = render(&theme());

        assert!(css.contains("--ml-primary: #FF235A;"));
        assert!(css.contains("#TabsToolbar"));
        assert!(css.contains("#nav-bar"));
        assert!(css.contains("#urlbar-background"));
        assert!(css.contains("border-radius: var(--ml-radius)"));
        assert!(Firefox.validate(&css).is_ok());
    }

    #[test]
    fn rejects_incomplete_browser_css() {
        assert!(Firefox.validate(":root { --ml-primary: #fff; }").is_err());
        assert!(Firefox.validate("#TabsToolbar { #nav-bar {").is_err());
    }

    #[test]
    fn reports_the_profile_stylesheet_destination() {
        assert_eq!(Firefox.relative_path(), "firefox/userChrome.css");
        assert_eq!(Firefox.programs(), &["firefox"]);
    }
}
